<div class="page-head"><div><h1><?= e($c['code']) ?> — <?= e($c['title']) ?></h1><p class="sub"><?= e(t('enum.committee.' . $c['committee'])) ?> · <?= e($c['meeting_date']) ?> · <?= status_badge($c['status']) ?></p></div>
<div class="actions"><a class="btn secondary" href="<?= e(url('committees')) ?>"><?= e(t('common.back')) ?></a><?php if (can('committee.manage')): ?><a class="btn" href="<?= e(url('committees/' . $c['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a><?php endif; ?></div></div>
<section class="card"><h2><?= e(t('cmt.decision')) ?></h2><p class="pre"><?= e($c['decision_text']) ?></p></section>
<section class="card" id="actions"><h2><?= e(t('cmt.followup')) ?></h2>
<?php if (!$actions): ?><p class="muted"><?= e(t('action.none')) ?></p><?php else: ?><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('action.title')) ?></th><th><?= e(t('action.owner')) ?></th><th><?= e(t('action.deadline')) ?></th><th><?= e(t('action.status')) ?></th></tr></thead><tbody>
<?php foreach ($actions as $a): $late = in_array($a['status'], ['not_started', 'in_progress'], true) && $a['deadline'] < date('Y-m-d'); ?><tr><td><?= e($a['title']) ?></td>
<?php if (can('committee.manage')): ?><td colspan="3"><form method="post" action="<?= e(url('committees/' . $c['id'] . '/actions/' . $a['id'])) ?>" class="filters"><?= csrf_field() ?>
<div class="field"><select name="owner_user_id" aria-label="<?= e(t('action.owner')) ?>"><?php foreach ($users as $x): ?><option value="<?= (int)$x['id'] ?>"<?= sel($a['owner_user_id'], $x['id']) ?>><?= e($x['full_name']) ?></option><?php endforeach; ?><?php if (!isset($users[(int)$a['owner_user_id']])): ?><option value="<?= (int)$a['owner_user_id'] ?>" selected><?= e($a['owner_name']) ?></option><?php endif; ?></select></div>
<div class="field"><input type="date" name="deadline" value="<?= e($a['deadline']) ?>" aria-label="<?= e(t('action.deadline')) ?>"><?= $late ? '<span class="badge danger">' . e(t('risk.overdue')) . '</span>' : '' ?></div>
<div class="field"><select name="status" aria-label="<?= e(t('action.status')) ?>"><?php foreach (['not_started', 'in_progress', 'completed', 'cancelled'] as $s): ?><option value="<?= $s ?>"<?= sel($a['status'], $s) ?>><?= e(enum_label('action_status', $s)) ?></option><?php endforeach; ?></select></div>
<div class="field"><button class="btn small secondary" type="submit"><?= e(t('common.update')) ?></button></div></form></td>
<?php else: ?><td><?= e($a['owner_name']) ?></td><td class="nowrap"><?= e($a['deadline']) ?><?= $late ? ' <span class="badge danger">' . e(t('risk.overdue')) . '</span>' : '' ?></td><td><?= e(enum_label('action_status', $a['status'])) ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if (can('committee.manage')): ?><details style="margin-top:12px"><summary><strong><?= e(t('action.add')) ?></strong></summary>
<form method="post" action="<?= e(url('committees/' . $c['id'] . '/actions')) ?>" class="form-grid" novalidate><?= csrf_field() ?>
<?= ff('text', 'title', 'action.title', '', ['required' => true, 'wide' => true]) ?><?= ff('select', 'owner_user_id', 'action.owner', '', ['required' => true, 'options' => opts($users, fn($x) => $x['full_name'])]) ?>
<?= ff('date', 'deadline', 'action.deadline', '', ['required' => true]) ?><?= ff('select', 'status', 'action.status', 'not_started', ['blank' => false, 'options' => opts(['not_started', 'in_progress', 'completed', 'cancelled'], fn($x) => enum_label('action_status', $x), null) ?: []]) ?>
<div class="field"><button class="btn" type="submit"><?= e(t('action.add')) ?></button></div></form></details><?php endif; ?></section>
